parameters.jsCode:
const coupons = $input.all();
const requestedCode = $('Redemption Webhook').first().json.body.coupon_code;
const match = coupons.find(c => c.json['Coupon Code'] === requestedCode);

if (!match) {
  return [{ json: { valid: false, message: 'Coupon not found' } }];
}

const expiry = new Date(match.json['Expiry Date']);
if (expiry < new Date()) {
  return [{ json: { valid: false, message: 'Coupon expired' } }];
}

if (match.json.Status !== 'Active') {
  return [{ json: { valid: false, message: 'Coupon already redeemed' } }];
}

return [{ json: { valid: true, couponCode: requestedCode, discount: match.json.Discount, message: 'Coupon valid' } }];
